/**
 * Stop every Bot computer running for one person now, and record it on the audit trail. Their Bots start a computer again when they next need one. Only an administrator may do this.
 * @summary Stop a person's computers
 */
export const stopPersonComputers = async (
  organizationId: string,
  personId: string,
  headers: StopPersonComputersHeaders,
  options?: Parameters<typeof apiRequest>[1],
): Promise<PersonComputersStopped> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<PersonComputersStopped>(
    getStopPersonComputersUrl(organizationId, personId),
    {
      ...options,
      method: "POST",
      headers: { ...headers, ...getHeaders(options?.headers) },
    },
  );
};

